import{_ as d,o,c as r,a2 as e}from"./chunks/framework.G0y0PQA7.js";const a="/relio/shots/ko/find-match-mode.png",i="/relio/shots/ko/find-hover-highlight.png",k=JSON.parse('{"title":"찾기와 강조","description":"","frontmatter":{},"headers":[],"relativePath":"features/find.md","filePath":"features/find.md"}'),n={name:"features/find.md"};function s(l,t,h,c,b,g){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="찾기와-강조" tabindex="-1">찾기와 강조 <a class="header-anchor" href="#찾기와-강조" aria-label="Permalink to &quot;찾기와 강조&quot;">​</a></h1><p>찾기 막대와 일치 방식, 한글 초성 찾기, 마우스 올림·선택 연결 강조, 강조 설정을 설명합니다.</p><p>짧은 사용법은 빠른 시작의 <a href="/relio/quick/navigate#찾기·강조">화면 다루기 › 찾기·강조</a>에 있습니다.</p><h2 id="찾기-막대" tabindex="-1">찾기 막대 <a class="header-anchor" href="#찾기-막대" aria-label="Permalink to &quot;찾기 막대&quot;">​</a></h2><p><kbd>Ctrl</kbd>+<kbd>F</kbd>(편집 › 찾기)를 누르면 캔버스 위에 찾기 막대가 열립니다.</p><ul><li>테이블·컬럼·관계·노트의 이름(물리명·논리명)을 치는 대로 찾습니다. 찾은 것은 모두 강조되고 나머지는 흐려집니다.</li><li><strong>한글 초성</strong>으로도 찾습니다. <code>ㅅㅇㅈ</code>을 치면 &quot;사용자&quot;를 찾습니다.</li><li>막대의 <strong>설명</strong> 옵션(테이블·컬럼 설명도 찾기)을 켜면 설명 글에서도 찾습니다.</li><li>막대에는 지금 결과 번호와 전체 개수가 &quot;3 / 12&quot;처럼 보이고, 없으면 &quot;결과 없음&quot;이 나옵니다. 막대의 <strong>테이블</strong> · <strong>컬럼</strong> · <strong>그 밖</strong> 단추는 어느 대상에서 찾을지 켜고 끄는 단추입니다.</li><li>막대 오른쪽의 <strong>…</strong> 단추(찾기·바꾸기…, <kbd>Ctrl</kbd>+<kbd>H</kbd>)로 <a href="/relio/features/edit#검색-창">검색 창</a>을 엽니다.</li><li><kbd>Esc</kbd>나 <strong>닫기</strong>로 막대를 닫으면 강조가 사라집니다.</li></ul><h3 id="결과-사이-옮기기" tabindex="-1">결과 사이 옮기기 <a class="header-anchor" href="#결과-사이-옮기기" aria-label="Permalink to &quot;결과 사이 옮기기&quot;">​</a></h3><table tabindex="0"><thead><tr><th>키</th><th>하는 일</th></tr></thead><tbody><tr><td><kbd>Enter</kbd> · <kbd>F3</kbd></td><td>다음 결과로 가서 그 결과를 한 번 깜빡입니다.</td></tr><tr><td><kbd>Shift</kbd>+<kbd>Enter</kbd> · <kbd>Shift</kbd>+<kbd>F3</kbd></td><td>이전 결과로 갑니다.</td></tr><tr><td><kbd>Alt</kbd>+<kbd>W</kbd></td><td>일치 방식을 바꿉니다.</td></tr><tr><td><kbd>Esc</kbd></td><td>막대를 닫습니다.</td></tr></tbody></table><p>마지막 결과에서 다음으로 가면 &quot;처음으로 돌아왔습니다&quot;가 나옵니다. 한글을 조합하는 중에 누른 <kbd>Enter</kbd>는 글자를 확정할 뿐 결과를 옮기지 않습니다.</p><h3 id="일치-방식" tabindex="-1">일치 방식 <a class="header-anchor" href="#일치-방식" aria-label="Permalink to &quot;일치 방식&quot;">​</a></h3><p>막대의 방식 단추(또는 <kbd>Alt</kbd>+<kbd>W</kbd>)를 누를 때마다 바뀌고, 고른 방식은 기억합니다.</p><table tabindex="0"><thead><tr><th>방식</th><th>맞는 경우</th><th>예: <code>ID</code>를 찾으면</th></tr></thead><tbody><tr><td>포함(기본)</td><td>이름 어디에나 있으면</td><td><code>MEMBER_ID</code>, <code>VALID</code> 모두</td></tr><tr><td>단어</td><td><code>_</code>·공백·기호와 대소문자 경계로 나뉜 조각이 같을 때</td><td><code>MEMBER_ID</code>·<code>memberId</code>는 맞고 <code>VALID</code>는 아님</td></tr><tr><td>전체 일치</td><td>이름 전체가 같을 때</td><td><code>ID</code>만</td></tr></tbody></table><p>단어·전체 일치에서는 초성 찾기를 쓰지 않습니다.</p><figure class="shot" data-scene="find-match-mode"><img src="'+a+'" alt="찾기 막대 — 일치 방식을 &quot;단어&quot;로 바꿔 ID를 찾은 모습" loading="lazy"><figcaption>찾기 막대 — 일치 방식을 &quot;단어&quot;로 바꿔 ID를 찾은 모습</figcaption></figure><h3 id="카테고리-화면에서-찾을-때" tabindex="-1">카테고리 화면에서 찾을 때 <a class="header-anchor" href="#카테고리-화면에서-찾을-때" aria-label="Permalink to &quot;카테고리 화면에서 찾을 때&quot;">​</a></h3><p>카테고리 탭에서는 그 범위 안에서만 강조합니다. 범위 밖에도 맞는 것이 있으면 &quot;이 카테고리 밖에 n개&quot;가 나오고 <strong>전체에서 보기</strong>로 &quot;전체&quot; 탭에서 다시 찾습니다. 표시를 끈 카테고리처럼 캔버스에 그리지 않은 대상에 맞으면 그 개수도 알려 줍니다. <a href="/relio/features/categories">카테고리</a></p><h2 id="연결-강조" tabindex="-1">연결 강조 <a class="header-anchor" href="#연결-강조" aria-label="Permalink to &quot;연결 강조&quot;">​</a></h2><ul><li><strong>마우스 올림</strong> — 테이블·관계선·컬럼에 마우스를 올리면 연결된 선과 테이블, 짝이 되는 기본 키(PK)·외래 키(FK) 컬럼이 조금 진하게 보입니다. 나머지는 그대로입니다.</li><li><strong>선택</strong> — 클릭해 고르면 연결된 것만 선명하고 나머지는 흐려집니다. 카테고리 영역을 고르면 테두리 선택 표시만 나옵니다.</li><li><strong>도구 설명</strong> — 테이블·컬럼에 마우스를 잠시 올리면 형식·NOT NULL·FK 대상·설명이 나옵니다.</li><li>문제 목록에서 항목을 누르면 그 객체로 가서 잠깐 강조합니다.</li></ul><p>강조는 화면에만 있고 이미지·HTML 내보내기와 인쇄에는 들어가지 않습니다.</p><figure class="shot" data-scene="find-hover-highlight"><img src="'+i+'" alt="테이블에 마우스를 올려 연결된 관계선·테이블·FK 컬럼이 진해진 모습" loading="lazy"><figcaption>테이블에 마우스를 올려 연결된 관계선·테이블·FK 컬럼이 진해진 모습</figcaption></figure><h2 id="강조-설정" tabindex="-1">강조 설정 <a class="header-anchor" href="#강조-설정" aria-label="Permalink to &quot;강조 설정&quot;">​</a></h2><p>도구 › 환경 설정 › 일반 › <strong>강조</strong>에서 바꿉니다. 바꾸는 즉시 적용되고, <strong>강조 미리 보기</strong>로 확인합니다.</p><table tabindex="0"><thead><tr><th>설정</th><th>값</th></tr></thead><tbody><tr><td>마우스 올림 연결 강조</td><td>켬 · 끔</td></tr><tr><td>선택 연결 강조</td><td>켬 · 끔</td></tr><tr><td>나머지 흐리게</td><td><strong>찾을 때</strong> · <strong>선택할 때</strong> 각각 켬 · 끔</td></tr><tr><td>흐림 정도</td><td>약하게 · 보통 · 강하게</td></tr><tr><td>강조 효과</td><td>깜빡임 · 서서히 줄어듦 · 고정, 그리고 <strong>횟수</strong> · <strong>한 번 길이</strong></td></tr><tr><td>움직임 줄이기</td><td>기본은 <strong>시스템 설정 따름</strong>. 켜면 깜빡이지 않고 굵은 테두리로만 보입니다.</td></tr></tbody></table><p>강조 효과는 찾기의 지금 결과와 목록에서 누른 대상에만 움직이고, 움직임은 늘 3초 안에 끝납니다.</p><div class="tip custom-block"><p class="custom-block-title">팁</p><p>화면이 자꾸 흐려지는 것이 불편하면 &quot;나머지 흐리게&quot;의 <strong>선택할 때</strong>만 끄세요. 찾을 때의 흐림은 남아 큰 모델에서 결과를 찾기 쉽습니다.</p></div>',25)])])}const p=d(n,[["render",s]]);export{k as __pageData,p as default};
